import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百三十八章 沉迷的滋味","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/238第二百三十八章 沉迷的滋味.md","filePath":"meditation/巴利文大藏经/238第二百三十八章 沉迷的滋味.md"}'),r={name:"meditation/巴利文大藏经/238第二百三十八章 沉迷的滋味.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百三十八章-沉迷的滋味" tabindex="-1">第二百三十八章 沉迷的滋味 <a class="header-anchor" href="#第二百三十八章-沉迷的滋味" aria-label="Permalink to &quot;第二百三十八章 沉迷的滋味&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应26经/乐味经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来证悟无上正等正觉之前，还是菩萨的时候，经常想这样的问题：「沉迷于物质事物、物质身体的滋味是什么？物质事物、物质身体的祸患是什么？如何从物质事物、物质身体中解脱出来？沉迷于感受、念想、行为、认识、分别、判断的滋味是什么？感受、念想、行为、认识、分别、判断的祸患是什么？如何从感受、念想、行为、认识、分别、判断中解脱出来？」</p><p>比丘们！如来那时是这样解答这个问题的：「由物质事物、物质身体生起快乐、喜悦，这就是沉迷于物质事物、物质身体的滋味。物质事物、物质身体是无法永远存在的，是无法永恒保持不变的，是随时在变化的，是最终带来痛苦的，这就是物质事物、物质身体的祸患。降伏熄灭对物质事物、物质身体的欲望、贪爱，除灭舍断对物质事物、物质身体的欲望、贪爱，不再执着和挂念物质事物、物质身体，这就是从物质事物、物质身体中解脱出来的方法。</p><p>由感受、念想、行为、认识、分别、判断生起快乐、喜悦，这就是沉迷于感受、念想、行为、认识、分别、判断的滋味。感受、念想、行为、认识、分别、判断是无法永远存在的，是无法永恒保持不变的，是随时在变化的，是最终带来痛苦的，这就是感受、念想、行为、认识、分别、判断的祸患。降伏熄灭对感受、念想、行为、认识、分别、判断的欲望、贪爱，除灭舍断对感受、念想、行为、认识、分别、判断的欲望、贪爱，不再执着和挂念感受、念想、行为、认识、分别、判断，这就是从感受、念想、行为、认识、分别、判断中解脱出来的方法。」</p><p>比丘们！如来如果没有证悟明白由物质事物、物质身体、感受、念想、行为、认识、分别、判断生起的烦恼，没有彻底明白：「沉迷于物质事物、物质身体的滋味是什么？物质事物、物质身体的祸患是什么？如何从物质事物、物质身体中解脱出来？沉迷于感受、念想、行为、认识、分别、判断的滋味是什么？感受、念想、行为、认识、分别、判断的祸患是什么？如何从感受、念想、行为、认识、分别、判断中解脱出来？」那么如来就无法证悟无上正等正觉，也就不能在人界、天界、魔界、梵天界等等众生所处的世间自称已经证悟了无上正等正觉的佛果，世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生也不会认可如来已经证悟了无上正等正觉，他们也不会接受如来的教导。</p><p>就是因为如来已经证悟明白了由物质事物、物质身体、感受、念想、行为、认识、分别、判断生起的烦恼，已经彻底明白了：「沉迷于物质事物、物质身体的滋味是什么？物质事物、物质身体的祸患是什么？如何从物质事物、物质身体中解脱出来？沉迷于感受、念想、行为、认识、分别、判断的滋味是什么？感受、念想、行为、认识、分别、判断的祸患是什么？如何从感受、念想、行为、认识、分别、判断中解脱出来？」如来才能证悟无上正等正觉，才能在人界、天界、魔界、梵天界等等众生所处的世间自称已经证悟了无上正等正觉的佛果，世间的普通人、出家人、修行人、天神、魔王、梵天王等等一切的众生才会认可如来已经证悟了无上正等正觉，他们才会接受如来的教导。</p><p>比丘们！如来用开启的智慧去实践修行，向所有世间的众生证明了按着这样的方法去修行可以从世间生死轮回的烦恼和痛苦中永远的解脱出来，如来已经不会再被世间任何的事物所困扰、迷惑，如来内心已经不会再被世间一切的事物所束缚捆绑，如来已经彻底永远的从世间解脱出来，如来知道自己这一世是最后一次出生在世间，如来以后不会再投生在世间，已经完全从世间的生死轮回中解脱出来。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',10)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
